import * as zod from 'zod';


/**
 * Sets the refresh token as an `HttpOnly; Secure; SameSite=Strict` cookie —
it is never in the response body, where script could read it.

**Failures are deliberately indistinguishable.** Wrong username, wrong
password and unknown user all return the same `invalid-credentials`
problem. Saying which field was wrong is a username-enumeration oracle.
Lockout after 5 failures for 15 minutes is reported as `account-locked`
only *after* correct credentials, for the same reason.

 * @summary Exchange credentials for an access token
 */
export const loginBodyUsernameMax = 100;


export const loginBodyTotpCodeRegExp = new RegExp('^\\d{6}$');


export const loginBody = zod.object({
  "username": zod.string().min(1).max(loginBodyUsernameMax),
  "password": zod.string().min(1),
  "totpCode": zod.string().regex(loginBodyTotpCodeRegExp).optional().describe('Required when 2FA is enabled.')
})

export const loginResponse = zod.object({
  "data": zod.object({
  "accessToken": zod.string(),
  "expiresIn": zod.number(),
  "mustChangePassword": zod.boolean().optional(),
  "landingRoute": zod.string().optional().describe('Role-based post-login destination, decided server-side — Admin and PM\nto the dashboard, Developer to My Tasks, Support to the ticket queue,\nQA and Deployment to the stage queue.\n'),
  "user": zod.object({
  "id": zod.number(),
  "displayName": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "role": zod.enum(['ADMIN', 'PM', 'DEVELOPER', 'QA', 'DEPLOYMENT', 'SUPPORT']).optional()
}).and(zod.object({
  "username": zod.string().optional(),
  "email": zod.string().email().optional(),
  "permissions": zod.array(zod.string()).optional(),
  "projectIds": zod.array(zod.number()).optional(),
  "reporteeIds": zod.array(zod.number()).optional(),
  "timezone": zod.string().optional()
}))
})
})

/**
 * Reads the refresh cookie; takes no body. The consumed token is revoked and
replaced on every call.

**Reuse of an already-consumed token means the token was stolen** — the
entire token family is revoked and the user must log in again. A silent
re-issue here would let an attacker keep a parallel session alive
indefinitely.

 * @summary Rotate the refresh token and issue a new access token
 */
export const refreshSessionResponse = zod.object({
  "data": zod.object({
  "accessToken": zod.string(),
  "expiresIn": zod.number(),
  "mustChangePassword": zod.boolean().optional(),
  "landingRoute": zod.string().optional().describe('Role-based post-login destination, decided server-side — Admin and PM\nto the dashboard, Developer to My Tasks, Support to the ticket queue,\nQA and Deployment to the stage queue.\n'),
  "user": zod.object({
  "id": zod.number(),
  "displayName": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "role": zod.enum(['ADMIN', 'PM', 'DEVELOPER', 'QA', 'DEPLOYMENT', 'SUPPORT']).optional()
}).and(zod.object({
  "username": zod.string().optional(),
  "email": zod.string().email().optional(),
  "permissions": zod.array(zod.string()).optional(),
  "projectIds": zod.array(zod.number()).optional(),
  "reporteeIds": zod.array(zod.number()).optional(),
  "timezone": zod.string().optional()
}))
})
})

/**
 * **Always returns 202**, whether or not the address is known. A different
response for unknown addresses is a user-enumeration oracle. The token is
single-use, 30-minute TTL, and stored hashed.

 * @summary Request a password-reset link
 */
export const forgotPasswordBody = zod.object({
  "email": zod.string().email()
})

/**
 * @summary Complete a password reset
 */
export const resetPasswordBodyTokenMin = 32;

export const resetPasswordBodyNewPasswordMin = 8;
export const resetPasswordBodyNewPasswordMax = 128;



export const resetPasswordBody = zod.object({
  "token": zod.string().min(resetPasswordBodyTokenMin),
  "newPassword": zod.string().min(resetPasswordBodyNewPasswordMin).max(resetPasswordBodyNewPasswordMax).describe('Upper, lower, digit and symbol required; the last three are not reusable.')
})

/**
 * @summary The authenticated user, with resolved permissions and scope
 */
export const getMeResponse = zod.object({
  "data": zod.object({
  "id": zod.number(),
  "displayName": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "role": zod.enum(['ADMIN', 'PM', 'DEVELOPER', 'QA', 'DEPLOYMENT', 'SUPPORT']).optional()
}).and(zod.object({
  "username": zod.string().optional(),
  "email": zod.string().email().optional(),
  "permissions": zod.array(zod.string()).optional(),
  "projectIds": zod.array(zod.number()).optional(),
  "reporteeIds": zod.array(zod.number()).optional(),
  "timezone": zod.string().optional()
}))
})

/**
 * Rejects reuse of the last three passwords. Clears `mustChangePassword`.
 * @summary Change own password
 */
export const changeOwnPasswordBodyNewPasswordMin = 8;
export const changeOwnPasswordBodyNewPasswordMax = 128;



export const changeOwnPasswordBody = zod.object({
  "currentPassword": zod.string(),
  "newPassword": zod.string().min(changeOwnPasswordBodyNewPasswordMin).max(changeOwnPasswordBodyNewPasswordMax).describe('Upper, lower, digit and symbol required; the last three are not reusable.')
})

